server {
    listen 443 ssl;
    server_name example.com;

    # 静态资源：Nginx 直接返回，不打扰后端
    location /static/ {
        root /var/www;
        expires 30d;
    }

    # 动态请求：转发给应用服务器
    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}

upstream backend {
    # 加权轮询：配置好的机器多分流量
    server 10.0.0.1:3000 weight=3;
    server 10.0.0.2:3000 weight=2;
    server 10.0.0.3:3000 weight=1;
    # ip_hash;  # 需要会话保持时打开：同一 IP 固定打到同一台
}

server {
    listen 80;
    location / {
        proxy_pass http://backend;
        proxy_next_upstream error timeout;  # 后端挂了自动换一台重试
    }
}

# 源站告诉 CDN 和浏览器：这个资源可以缓存多久
location /static/ {
    # 图片视频：CDN 缓存 30 天，浏览器缓存 7 天
    expires 30d;
    add_header Cache-Control "public, max-age=2592000";
}

location /api/ {
    # 动态接口：不允许 CDN 缓存
    add_header Cache-Control "no-store";
}

# 带 hash 文件名的资源：可永久缓存
# app.a3f9c2.js -> 一年后也不会变，变了文件名就变了
location ~* \.[a-f0-9]{8}\.(js|css)$ {
    expires 1y;
}

import logging, json

# 结构化日志：JSON 格式，带 traceId，方便集中检索
class JsonFormatter(logging.Formatter):
    def format(self, record):
        return json.dumps({
            "time": self.formatTime(record),
            "level": record.levelname,
            "trace_id": getattr(record, "trace_id", "-"),
            "msg": record.getMessage(),
        }, ensure_ascii=False)

handler = logging.StreamHandler()
handler.setFormatter(JsonFormatter())
logger = logging.getLogger("app")
logger.addHandler(handler)

